 changes+='<details><summary>'+esc(label)+'</summary><div class="pair"><div><b>Before</b><pre>'+esc(summary(u['before']))+'</pre></div><div><b>After</b><pre>'+esc(summary(u['after']))+'</pre></div></div></details>'
